// Schema validation for sensor readings
const payload = msg.payload;

// Required fields check
const required = ['deviceId', 'buildingId', 'roomId', 'sensorType', 'timestamp'];
for (const field of required) {
    if (!payload[field]) {
        msg.validationError = `Missing required field: ${field}`;
        return [null, msg]; // Route to dead-letter
    }
}

// Type-specific validation
if (payload.sensorType === 'motion') {
    if (typeof payload.motion !== 'boolean') {
        msg.validationError = 'motion field must be boolean';
        return [null, msg];
    }
    payload.value = payload.motion;
} else if (payload.sensorType === 'lux') {
    if (typeof payload.lux !== 'number' || payload.lux < 0 || payload.lux > 1000) {
        msg.validationError = `Invalid lux value: ${payload.lux}`;
        return [null, msg];
    }
    payload.value = payload.lux;
} else {
    msg.validationError = `Unknown sensorType: ${payload.sensorType}`;
    return [null, msg];
}

msg.payload = payload;
return [msg, null]; // Valid → continue pipeline

// This node acts as a lightweight proxy.
// Complex rule logic is handled by the Rule Engine microservice.
// This flow monitors and logs rule trigger events.

const event = msg.payload;
node.status({fill:'green', shape:'dot', text:`${event.buildingId}/${event.roomId}`});

// Forward to Rule Engine microservice via its MQTT subscription
msg.topic = `rules/evaluate/${event.buildingId}/${event.roomId}`;
return msg;

// Compute 5-minute rolling average of lux per room
const WINDOW_MS = 300000; // 5 minutes
const event = msg.payload;
const key = `${event.buildingId}:${event.roomId}`;

// Initialize context storage
let windows = context.get('windows') || {};
if (!windows[key]) windows[key] = [];

const now = Date.now();

if (event.sensorType === 'lux') {
    windows[key].push({ value: event.lux, ts: now });
    // Trim window
    windows[key] = windows[key].filter(e => (now - e.ts) < WINDOW_MS);

    const sum = windows[key].reduce((a, e) => a + e.value, 0);
    const avgLux = Math.round(sum / windows[key].length);

    msg.payload.avgLux = avgLux;
    msg.payload.windowSize = windows[key].length;
}

context.set('windows', windows);

// Format for dashboard display
msg.payload.displayLabel = `${event.buildingId}/${event.roomId}`;
if (event.sensorType === 'motion') {
    msg.payload.displayValue = event.motion ? '🟢 MOTION' : '⚪ Clear';
} else {
    msg.payload.displayValue = `${event.lux} lux (avg: ${msg.payload.avgLux || 'N/A'})`;
}

return msg;

const event = msg.payload;
const parts = msg.topic.split('/');
msg.payload = {
    displayLabel: `${parts[1]}/${parts[2]} Light`,
    displayValue: `💡 ${event.command} (Rule: ${event.ruleId || 'manual'})`,
    command: event.command,
    ruleId: event.ruleId,
    timestamp: event.timestamp
};
return msg;
